using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPut("{id:int}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
        {
            var shipment = await service.UpdateShipmentStatusAsync(id, request.Status);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });
    }
}

public record StatusUpdateRequest(ShipmentStatus Status);

using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        await db.Database.EnsureCreatedAsync();

        if (db.Shipments.Any())
            return;

        var now = DateTime.UtcNow;
        db.Shipments.AddRange(
            new Shipment
            {
                TrackingNumber = "TRK-10001",
                Origin = "New York, NY",
                Destination = "Los Angeles, CA",
                Status = 2, // InTransit
                CreatedAt = now.AddDays(-3),
                EstimatedDelivery = now.AddDays(2),
                RecipientName = "Alice Johnson",
                Description = "Electronics — 2 boxes"
            },
            new Shipment
            {
                TrackingNumber = "TRK-10002",
                Origin = "Chicago, IL",
                Destination = "Miami, FL",
                Status = 1, // PickedUp
                CreatedAt = now.AddDays(-1),
                EstimatedDelivery = now.AddDays(4),
                RecipientName = "Bob Smith",
                Description = "Furniture — 1 pallet"
            },
            new Shipment
            {
                TrackingNumber = "TRK-10003",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = 3, // OutForDelivery
                CreatedAt = now.AddDays(-5),
                EstimatedDelivery = now,
                RecipientName = "Carol Davis",
                Description = "Medical supplies"
            },
            new Shipment
            {
                TrackingNumber = "TRK-10004",
                Origin = "Houston, TX",
                Destination = "Boston, MA",
                Status = 4, // Delivered
                CreatedAt = now.AddDays(-7),
                EstimatedDelivery = now.AddDays(-2),
                RecipientName = "Dan Wilson",
                Description = "Auto parts — 3 boxes"
            },
            new Shipment
            {
                TrackingNumber = "TRK-10005",
                Origin = "San Francisco, CA",
                Destination = "Portland, OR",
                Status = 0, // Pending
                CreatedAt = now,
                EstimatedDelivery = now.AddDays(3),
                RecipientName = "Eva Martinez",
                Description = "Clothing shipment"
            }
        );
        await db.SaveChangesAsync();
    }
}

